-- One-time cleanup: the household's recipes read from photos are replaced by the 244 recipes
-- transcribed by hand from those photos. Scans with the same name are updated in place (their
-- stars, favorites and plans stay); other scans are removed; recipes from links, Pinterest or
-- typed by hand are left alone.
CREATE TABLE "_recipe_file" (
	"title" text NOT NULL,
	"description" text,
	"servings" integer,
	"prep_minutes" integer,
	"cook_minutes" integer,
	"ingredients" jsonb NOT NULL,
	"steps" jsonb NOT NULL,
	"tags" jsonb NOT NULL,
	"meal_types" jsonb NOT NULL,
	"notes" text,
	"source_url" text
);
--> statement-breakpoint
