DELETE FROM "recipes"
WHERE "household_id" = (SELECT "household_id" FROM "users" ORDER BY "created_at" ASC LIMIT 1)
	AND "source_type" IN ('photo', 'text')
	AND lower(trim("title")) NOT IN (SELECT lower(trim("title")) FROM "_recipe_file");
--> statement-breakpoint
UPDATE "recipes" AS r SET
	"title" = f."title",
	"description" = f."description",
	"servings" = f."servings",
	"prep_minutes" = f."prep_minutes",
	"cook_minutes" = f."cook_minutes",
	"total_minutes" = NULL,
	"ingredients" = f."ingredients",
	"steps" = f."steps",
	"tags" = f."tags",
	"meal_types" = f."meal_types",
	"notes" = f."notes",
	"source_url" = f."source_url",
	"title_by_hand" = true,
	"read_with" = 'claude',
	"updated_at" = now()
FROM "_recipe_file" AS f
WHERE r."household_id" = (SELECT "household_id" FROM "users" ORDER BY "created_at" ASC LIMIT 1)
	AND r."source_type" IN ('photo', 'text')
	AND lower(trim(r."title")) = lower(trim(f."title"));
--> statement-breakpoint
INSERT INTO "recipes" ("id", "household_id", "title", "description", "servings", "prep_minutes", "cook_minutes", "ingredients", "steps", "tags", "meal_types", "notes", "source_url", "source_type", "title_by_hand", "read_with", "created_by")
SELECT gen_random_uuid()::text, h."id", f."title", f."description", f."servings", f."prep_minutes", f."cook_minutes", f."ingredients", f."steps", f."tags", f."meal_types", f."notes", f."source_url", 'photo', true, 'claude', 'Household'
FROM "_recipe_file" AS f
CROSS JOIN (SELECT (SELECT "household_id" FROM "users" ORDER BY "created_at" ASC LIMIT 1) AS "id") AS h
WHERE h."id" IS NOT NULL
	AND NOT EXISTS (SELECT 1 FROM "recipes" AS r WHERE r."household_id" = h."id" AND lower(trim(r."title")) = lower(trim(f."title")));
--> statement-breakpoint
DELETE FROM "imported_photos" WHERE "recipe_id" IS NULL;
